// Daily user journey + Gemini-powered recommendation cards.
//
// /api/recovery/journey
//   Returns the survivor's 6-step daily plan with per-step completion state
//   computed from existing tables (no new schema). Steps in order: morning
//   check-in → bonfire → Coach → Anchor → Brain Gym → evening journal.
//
// /api/recovery/recommendations?surface=journey|welcome|dashboard|...
//   Returns 1–2 contextual recommendation cards. Card copy is generated by
//   Gemini per (userId, surface, day) and cached in-memory for 24h. Falls
//   back to a hand-curated static rotation when Gemini is unavailable so the
//   surface never empties out.
//
// Mounted from server/routes.ts after setupAuth().
import type { Express, Request, Response } from "express";
import { db } from "./db";
import { sql } from "drizzle-orm";
import { isAuthenticated } from "./replitAuth";
import { getUserId } from "./lib/authUtils";
import { getCanonicalSurvivorProfile } from "./survivorProfileService";
import { GoogleGenAI } from "@google/genai";
import { z } from "zod";
import { requireAdmin } from "./middleware/requireAdmin";
import {
  buildRecoverySummary,
  buildSummaryPilotReport,
  canAccessRecoverySummary,
  getActorSummaryMeasurement,
  recordSummaryEvent,
  summaryIdForWindow,
} from "./recoverySummaryService";
import {
  sampleQuotePool,
  getQuotesByCategory,
  getRandomQuote,
} from "./data/nickQuotes";

// ── Step catalog ─────────────────────────────────────────────────────────
// Outcome-framed copy, never feature-framed. Each step deep-links to the
// existing surface that owns it. No new pages required.
type StepKey =
  | "checkin"
  | "bonfire"
  | "coach"
  | "anchor"
  | "braingym"
  | "journal";

type Step = {
  key: StepKey;
  title: string;
  subtitle: string;
  href: string;
  icon: string;
  completed: boolean;
};

