// Lazy Gemini client — initialized on first call. We don't crash if the
// key is missing; we just always serve fallback copy.
let geminiClient: GoogleGenAI | null = null;
function getGemini(): GoogleGenAI | null {
  if (geminiClient) return geminiClient;
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) return null;
  try {
    geminiClient = new GoogleGenAI({ apiKey });
    return geminiClient;
  } catch {
    return null;
  }
}

let geminiFallbackLogged = false;

async function generateRecommendations(args: {
  surface: string;
  completedToday: StepKey[];
  notDoneToday: StepKey[];
  streak: number;
  isPremium: boolean;
  userId?: string | null;
}): Promise<RecommendationCard[]> {
  const ai = getGemini();
  if (!ai) return STATIC_FALLBACK[args.surface] ?? STATIC_FALLBACK.journey;

  // Build the recommendation pool — never recommend something the survivor
  // already did today, never recommend Premium when they haven't earned the
  // conversation yet (streak < 3 OR no completed step today).
  const showPremium = args.streak >= 3 && args.completedToday.length >= 1 && !args.isPremium;

  const candidatePool: Array<{ key: string; href: string; outcome: string }> = [
    ...args.notDoneToday.map((k) => ({
      key: k,
      href: STEPS.find((s) => s.key === k)!.href,
      outcome: STEPS.find((s) => s.key === k)!.subtitle,
    })),
  ];
  if (showPremium) {
    candidatePool.push({
      key: "premium",
      href: "/recovery/premium",
      outcome:
        "Sasquatch Premium = unlimited Coach, unlimited Anchors, Voice Cloning included.",
    });
  }
  if (candidatePool.length === 0) {
    // They've done everything — congratulate, don't pitch.
    return [
      {
        id: "all-done",
        quote: "Six for six. The fire is warm tonight.",
        body: "You completed every step today. Tomorrow it resets. Sleep well, survivor.",
        ctaLabel: "See your streak",
        ctaHref: "/recovery/dashboard",
        icon: "star",
      },
    ];
  }

  // Pull 8 candidate quotes in Nick's actual voice, drawn from his book
  // + Doctrine + Manifesto. The model is required to pick its `quote`
  // verbatim from this pool — eliminates the "generic motivational copy"
  // drift Gemini gravitates toward. Only `body` + `ctaLabel` are model-
  // generated, and only against the candidate pool.
  const quotePool = sampleQuotePool({
    surface: args.surface,
    streak: args.streak,
    isPremium: args.isPremium,
    userId: args.userId,
  });
  const quotePoolSet = new Set(quotePool);

  const prompt = [
    "You are Sasquatch — a dry, warm, survivor-to-survivor voice for a stroke recovery platform built by Nick Kremers (7-year stroke survivor, founder).",
    "Generate 1 to 2 recommendation cards for a survivor.",
    "",
    "STRICT RULES:",
    "  - The `quote` field MUST be copied verbatim from the QUOTE POOL below. Do not paraphrase, shorten, or invent quotes. These are Nick's actual book lines.",
    "  - The `body` field is one sentence (≤ 30 words) explaining why this card matters for THIS survivor right now. Tie the quote to the action.",
    "  - `ctaLabel` is a 2-4 word action label.",
    "  - `ctaHref` MUST be picked from the CANDIDATE POOL below.",
    "  - `icon` is one of: music, messageCircle, flame, brain, pencil, sun, sparkles, star, compass.",
    "  - No exclamation points. No emoji. No marketing jargon. Never start with 'Hey' or 'Hi'.",
    "  - Never recommend premium if premium=true.",
    "",
    `Survivor state: streak=${args.streak} days, completed today=[${args.completedToday.join(",") || "none"}], premium=${args.isPremium}.`,
    `Surface: ${args.surface}.`,
    "",
    "QUOTE POOL (pick `quote` verbatim from one of these):",
    ...quotePool.map((q) => `  - "${q}"`),
    "",
    "CANDIDATE POOL (ctaHref must be one of these exact paths):",
    ...candidatePool.map((c) => `  - "${c.href}": ${c.outcome}`),
    "",
    "Return ONLY a JSON object: {\"items\": [{\"quote\":\"\",\"body\":\"\",\"ctaLabel\":\"\",\"ctaHref\":\"\",\"icon\":\"\"}]}.",
  ].join("\n");

  try {
    const resp = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        temperature: 0.8,
      },
    });
    const text = resp.text ?? "";
    // Strip code fences if any, then take outermost {...}.
    const cleaned = text.replace(/```json|```/g, "").trim();
    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");
    if (start === -1 || end === -1) throw new Error("no json");
    const parsed = JSON.parse(cleaned.slice(start, end + 1));
    const items = Array.isArray(parsed?.items) ? parsed.items : [];
    const allowedHrefs = new Set(candidatePool.map((c) => c.href));
    const cleanItems: RecommendationCard[] = items
      .slice(0, 2)
      .filter((it: any) => it && typeof it === "object")
      .map((it: any, idx: number) => {
        // Verbatim guard: if Gemini paraphrases or invents a quote, fall
        // back to the first library quote in the pool so every shipped
        // card is guaranteed to be in Nick's actual voice.
        const rawQuote = String(it.quote ?? "").trim();
        const quote = quotePoolSet.has(rawQuote) ? rawQuote : quotePool[0];
        return {
          id: `gemini-${args.surface}-${idx}`,
          quote: quote.slice(0, 200),
          body: String(it.body ?? "").slice(0, 280),
          ctaLabel: String(it.ctaLabel ?? "Try it").slice(0, 32),
          ctaHref: allowedHrefs.has(String(it.ctaHref))
            ? String(it.ctaHref)
            : candidatePool[0].href,
          icon: String(it.icon ?? "sparkles").slice(0, 32),
        };
      })
      .filter((c: RecommendationCard) => c.quote.length > 0 && c.body.length > 0);
    if (cleanItems.length === 0) throw new Error("empty");
    return cleanItems;
  } catch (e: any) {
    if (!geminiFallbackLogged) {
      geminiFallbackLogged = true;
      console.warn(
        "[journey/recommendations] Gemini unavailable; serving static fallback:",
        e?.message || e,
      );
    }
    return STATIC_FALLBACK[args.surface] ?? STATIC_FALLBACK.journey;
  }
}

export function registerRecoveryJourneyRoutes(app: Express) {
  const summaryFeedbackSchema = z.object({
    phase: z.enum(["before", "after"]),
    usefulness: z.number().int().min(1).max(5),
    uncertainty: z.number().int().min(1).max(5),
  }).strict();

  app.get(
    "/api/recovery/summary",
    isAuthenticated,
    async (req: Request, res: Response) => {
      try {
        const userId = getUserId(req);
        if (!userId) return res.status(401).json({ message: "Unauthorized" });
        const windowDays = Number(req.query.windowDays ?? 14);
        const summary = await buildRecoverySummary(userId, windowDays);
        const measurement = await getActorSummaryMeasurement(userId, summary.summaryId);
        await recordSummaryEvent({
          survivorId: userId,
          actorId: userId,
          actorType: "survivor",
          eventType: "summary_viewed",
          summaryId: summary.summaryId,
        });
        res.json({ ...summary, measurement });
      } catch (e: any) {
        console.error("[recovery/summary] failed", e?.message || e);
        res.status(500).json({ message: "Failed to load recovery summary" });
      }
    },
  );

  app.post(
    "/api/recovery/summary/feedback",
    isAuthenticated,
    async (req: Request, res: Response) => {
      try {
        const userId = getUserId(req);
        if (!userId) return res.status(401).json({ message: "Unauthorized" });
        const parsed = summaryFeedbackSchema.safeParse(req.body ?? {});
        if (!parsed.success) return res.status(400).json({ message: "Invalid summary rating" });
        const summaryId = summaryIdForWindow(14);
        await recordSummaryEvent({
          survivorId: userId,
          actorId: userId,
          actorType: "survivor",
          eventType: "feedback_submitted",
          summaryId,
          ...parsed.data,
        });
        res.json({ ok: true, measurement: await getActorSummaryMeasurement(userId, summaryId) });
      } catch (e: any) {
        console.error("[recovery/summary/feedback] failed", e?.message || e);
        res.status(500).json({ message: "Failed to save summary rating" });
      }
    },
  );

  app.get(
    "/api/admin/recovery/summary-pilot-report",
    isAuthenticated,
    requireAdmin,
    async (req: Request, res: Response) => {
      try {
        res.json(await buildSummaryPilotReport(Number(req.query.windowDays ?? 90)));
      } catch (e: any) {
        console.error("[admin/recovery/summary-pilot-report] failed", e?.message || e);
        res.status(500).json({ message: "Failed to build pilot report" });
      }
    },
  );

  // ── GET /api/recovery/journey ──────────────────────────────────────────
  app.get(
    "/api/recovery/journey",
    isAuthenticated,
    async (req: Request, res: Response) => {
      try {
        const userId = getUserId(req);
        if (!userId) return res.status(401).json({ message: "Unauthorized" });
        const dayStr = todayUtcKey();

        // 7 fully-parallel reads. Every query is one row at most.
        const [
          rCheckin,
          rBonfire,
          rCoach,
          rAnchor,
          rBraingym,
          rJournal,
          rStreak,
          profile,
        ] = await Promise.all([
          db.execute(
            sql`SELECT 1 FROM daily_checkins WHERE user_id = ${userId} AND checkin_date::date = CURRENT_DATE LIMIT 1`,
          ),
          db.execute(
            sql`SELECT 1 FROM routine_completions WHERE user_id = ${userId} AND date = ${dayStr} LIMIT 1`,
          ),
          db.execute(
            sql`SELECT 1 FROM coach_daily_usage WHERE user_id = ${userId} AND usage_date = ${dayStr} AND count > 0 LIMIT 1`,
          ),
          db.execute(
            sql`SELECT 1 FROM recovery_anchors WHERE user_id = ${userId} AND created_at::date = CURRENT_DATE LIMIT 1`,
          ),
          db.execute(
            sql`SELECT 1 FROM brain_gym_completions WHERE user_id = ${userId} AND completed_at::date = CURRENT_DATE LIMIT 1`,
          ),
          db.execute(
            sql`SELECT 1 FROM recovery_journals WHERE user_id = ${userId} AND created_at::date = CURRENT_DATE LIMIT 1`,
          ),
          db.execute(
            sql`SELECT current_streak, longest_streak, total_active_days FROM user_streaks WHERE user_id = ${userId} LIMIT 1`,
          ),
          getCanonicalSurvivorProfile(userId),
        ]);

        const completedMap: Record<StepKey, boolean> = {
          checkin: (rCheckin.rows?.length ?? 0) > 0,
          bonfire: (rBonfire.rows?.length ?? 0) > 0,
          coach: (rCoach.rows?.length ?? 0) > 0,
          anchor: (rAnchor.rows?.length ?? 0) > 0,
          braingym: (rBraingym.rows?.length ?? 0) > 0,
          journal: (rJournal.rows?.length ?? 0) > 0,
        };

        const steps: Step[] = STEPS.map((s) => ({
          ...s,
          completed: completedMap[s.key],
        }));
        const completedCount = steps.filter((s) => s.completed).length;
        const nextStep = steps.find((s) => !s.completed) ?? null;

        const sRow = (rStreak.rows?.[0] ?? {}) as Record<string, unknown>;
        const streak = {
          current: Number(sRow.current_streak ?? 0),
          longest: Number(sRow.longest_streak ?? 0),
          totalActive: Number(sRow.total_active_days ?? 0),
        };

        res.json({
          date: dayStr,
          streak,
          steps,
          completedCount,
          totalCount: steps.length,
          nextStep,
          profile: profile ? {
            ...profile,
            intakeComplete: !!profile.intakeCompletedAt,
          } : null,
        });
      } catch (e: any) {
        console.error("[journey] failed", e?.message || e);
        res.status(500).json({ message: "Failed to load journey" });
      }
    },
  );

  // ── GET /api/recovery/recommendations?surface=... ──────────────────────
  app.get(
    "/api/recovery/recommendations",
    isAuthenticated,
    async (req: Request, res: Response) => {
      try {
        const userId = getUserId(req);
        if (!userId) return res.status(401).json({ message: "Unauthorized" });

        const surface = String(req.query.surface ?? "journey")
          .replace(/[^a-z0-9_-]/gi, "")
          .slice(0, 32) || "journey";
        const dayStr = todayUtcKey();
        const cacheKey = `${userId}:${surface}:${dayStr}`;
        const cached = recCache.get(cacheKey);
        if (cached && cached.expiresAt > Date.now()) {
          return res.json({ surface, items: cached.value });
        }

        // Compute "what hasn't been done today" so Gemini can recommend it.
        // Also fetch streak + premium status so we never recommend premium
        // to someone who already has it or hasn't earned the conversation.
        const dayKey = dayStr;
        const [rJourney, rPremium] = await Promise.all([
          (async () => {
            const [rC, rB, rCo, rA, rBg, rJ, rS] = await Promise.all([
              db.execute(sql`SELECT 1 FROM daily_checkins WHERE user_id = ${userId} AND checkin_date::date = CURRENT_DATE LIMIT 1`),
              db.execute(sql`SELECT 1 FROM routine_completions WHERE user_id = ${userId} AND date = ${dayKey} LIMIT 1`),
              db.execute(sql`SELECT 1 FROM coach_daily_usage WHERE user_id = ${userId} AND usage_date = ${dayKey} AND count > 0 LIMIT 1`),
              db.execute(sql`SELECT 1 FROM recovery_anchors WHERE user_id = ${userId} AND created_at::date = CURRENT_DATE LIMIT 1`),
              db.execute(sql`SELECT 1 FROM brain_gym_completions WHERE user_id = ${userId} AND completed_at::date = CURRENT_DATE LIMIT 1`),
              db.execute(sql`SELECT 1 FROM recovery_journals WHERE user_id = ${userId} AND created_at::date = CURRENT_DATE LIMIT 1`),
              db.execute(sql`SELECT current_streak FROM user_streaks WHERE user_id = ${userId} LIMIT 1`),
            ]);
            return {
              completed: {
                checkin: (rC.rows?.length ?? 0) > 0,
                bonfire: (rB.rows?.length ?? 0) > 0,
                coach: (rCo.rows?.length ?? 0) > 0,
                anchor: (rA.rows?.length ?? 0) > 0,
                braingym: (rBg.rows?.length ?? 0) > 0,
                journal: (rJ.rows?.length ?? 0) > 0,
              },
              streak: Number((rS.rows?.[0] as any)?.current_streak ?? 0),
            };
          })(),
          // Premium check is best-effort; if it errors we just assume free.
          (async () => {
            try {
              const { isSasquatchPremium } = await import(
                "./services/sasquatchPremiumService"
              );
              return await isSasquatchPremium(userId);
            } catch {
              return false;
            }
          })(),
        ]);

        const completedToday = (Object.entries(rJourney.completed) as Array<[StepKey, boolean]>)
          .filter(([, v]) => v)
          .map(([k]) => k);
        const notDoneToday = (Object.entries(rJourney.completed) as Array<[StepKey, boolean]>)
          .filter(([, v]) => !v)
          .map(([k]) => k);

        const items = await generateRecommendations({
          surface,
          completedToday,
          notDoneToday,
          streak: rJourney.streak,
          isPremium: rPremium,
          userId,
        });

        recCache.set(cacheKey, { value: items, expiresAt: Date.now() + REC_TTL_MS });
        res.json({ surface, items });
      } catch (e: any) {
        console.error("[recommendations] failed", e?.message || e);
        // Always return SOMETHING so the UI never breaks.
        res.json({
          surface: String(req.query.surface ?? "journey"),
          items: STATIC_FALLBACK.journey,
        });
      }
    },
  );

  // ── GET /api/recovery/spark ────────────────────────────────────────────
  // Today's Spark — a single Nick quote, deterministic per (userId, day).
  // Same survivor sees the same line all day, fresh quote tomorrow. No
  // LLM call, no DB write — pure library lookup.
  app.get(
    "/api/recovery/spark",
    isAuthenticated,
    async (req: Request, res: Response) => {
      try {
        const userId = getUserId(req) ?? "anon";
        const { getDailyQuote } = await import("./data/nickQuotes");
        const q = getDailyQuote(userId);
        // Deterministic per (userId, day) — same survivor sees the same line
        // all day. private + 1h max-age means a hard reload short-circuits at
        // the browser cache instead of running the picker again. `Vary: Cookie`
        // prevents the cached response from replaying across an account switch
        // in the same browser profile (different session cookie → cache miss).
        res.set("Cache-Control", "private, max-age=3600");
        res.set("Vary", "Cookie");
        res.json({ text: q.text, category: q.category });
      } catch (e: any) {
        console.error("[spark] failed", e?.message || e);
        const fallback = getRandomQuote();
        res.json({ text: fallback.text, category: fallback.category });
      }
    },
  );
}
